From 7b8937197f131b5f5197804835d92c335927e943 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 17:49:04 +0100
Subject: [PATCH] kcms/notifications: allow playing a sound for apps without
 events

Applications that don't ship their own notification events, like web
browsers, had no way to play a sound for their notifications. Add a
"Play a sound" option with a sound picker to their settings page.

BUG: 435774
---
 kcms/notifications/kcm.cpp                    |  8 ++
 .../ui/ApplicationConfiguration.qml           | 77 +++++++++++++++++++
 .../kcfg/behaviorsettings.kcfg                |  6 ++
 libnotificationmanager/notifications.cpp      | 16 ++++
 4 files changed, 107 insertions(+)

diff --git a/kcms/notifications/kcm.cpp b/kcms/notifications/kcm.cpp
index 41c63aee90..128b90a03f 100644
--- a/kcms/notifications/kcm.cpp
+++ b/kcms/notifications/kcm.cpp
@@ -271,6 +271,8 @@ void KCMNotifications::createConnections(NotificationManager::BehaviorSettings *
     connect(settings, &NotificationManager::BehaviorSettings::ShowPopupsInDndModeChanged, this, &KCMNotifications::settingsChanged);
     connect(settings, &NotificationManager::BehaviorSettings::ShowInHistoryChanged, this, &KCMNotifications::settingsChanged);
     connect(settings, &NotificationManager::BehaviorSettings::ShowBadgesChanged, this, &KCMNotifications::settingsChanged);
+    connect(settings, &NotificationManager::BehaviorSettings::PlaySoundChanged, this, &KCMNotifications::settingsChanged);
+    connect(settings, &NotificationManager::BehaviorSettings::SoundChanged, this, &KCMNotifications::settingsChanged);

     connect(settings, &NotificationManager::BehaviorSettings::ShowPopupsChanged, this, [this, index] {
         updateModelIsDefaultStatus(index);
@@ -284,6 +286,12 @@ void KCMNotifications::createConnections(NotificationManager::BehaviorSettings *
     connect(settings, &NotificationManager::BehaviorSettings::ShowBadgesChanged, this, [this, index] {
         updateModelIsDefaultStatus(index);
     });
+    connect(settings, &NotificationManager::BehaviorSettings::PlaySoundChanged, this, [this, index] {
+        updateModelIsDefaultStatus(index);
+    });
+    connect(settings, &NotificationManager::BehaviorSettings::SoundChanged, this, [this, index] {
+        updateModelIsDefaultStatus(index);
+    });
 }

 QUrl KCMNotifications::soundsLocation()
diff --git a/kcms/notifications/ui/ApplicationConfiguration.qml b/kcms/notifications/ui/ApplicationConfiguration.qml
index a07978ea88..f0eb0e3eae 100644
--- a/kcms/notifications/ui/ApplicationConfiguration.qml
+++ b/kcms/notifications/ui/ApplicationConfiguration.qml
@@ -128,6 +128,79 @@ ColumnLayout {
                         }
                     }

+                    RowLayout {
+                        visible: eventsList.count === 0
+
+                        QQC2.CheckBox {
+                            id: playSoundCheck
+                            Layout.leftMargin: mirrored ? 0 : indicator.width
+                            Layout.rightMargin: mirrored ? indicator.width : 0
+                            text: i18n("Play a sound")
+                            checked: !!behaviorSettings && behaviorSettings.playSound
+                            onClicked: behaviorSettings.playSound = checked
+
+                            KCM.SettingStateBinding {
+                                configObject: behaviorSettings
+                                settingName: "PlaySound"
+                                extraEnabledConditions: showPopupsCheck.checked
+                            }
+                        }
+
+                        QQC2.Button {
+                            enabled: playSoundCheck.enabled && !!behaviorSettings?.sound
+                            display: QQC2.AbstractButton.IconOnly
+                            icon.name: "media-playback-start"
+                            text: i18nc("@info:tooltip", "Preview sound")
+
+                            QQC2.ToolTip.delay: Kirigami.Units.toolTipDelay
+                            QQC2.ToolTip.text: text
+                            QQC2.ToolTip.visible: hovered || activeFocus
+
+                            onClicked: kcm.playSound(behaviorSettings.sound)
+                        }
+                        QQC2.TextField {
+                            text: behaviorSettings?.sound ?? ""
+                            onEditingFinished: behaviorSettings.sound = text
+
+                            Layout.fillWidth: true
+                            Layout.maximumWidth: implicitWidth
+                            Layout.minimumWidth: Kirigami.Units.gridUnit * 5
+
+                            KCM.SettingStateBinding {
+                                configObject: behaviorSettings
+                                settingName: "Sound"
+                                extraEnabledConditions: playSoundCheck.enabled && playSoundCheck.checked
+                            }
+                        }
+                        QQC2.Button {
+                            enabled: playSoundCheck.enabled && playSoundCheck.checked && behaviorSettings?.sound !== behaviorSettings?.defaultSoundValue
+                            display: QQC2.AbstractButton.IconOnly
+                            icon.name: "edit-reset"
+                            text: i18nc("Reset the notification sound to a default one", "Reset")
+
+                            QQC2.ToolTip.delay: Kirigami.Units.toolTipDelay
+                            QQC2.ToolTip.text: text
+                            QQC2.ToolTip.visible: hovered || activeFocus
+
+                            onClicked: behaviorSettings.sound = behaviorSettings.defaultSoundValue
+                        }
+                        QQC2.Button {
+                            enabled: playSoundCheck.enabled && playSoundCheck.checked
+                            display: QQC2.AbstractButton.IconOnly
+                            icon.name: "document-open-folder"
+                            text: i18n("Choose sound file")
+
+                            QQC2.ToolTip.delay: Kirigami.Units.toolTipDelay
+                            QQC2.ToolTip.text: text
+                            QQC2.ToolTip.visible: hovered || activeFocus
+
+                            onClicked: {
+                                soundSelector.eventRow = -1
+                                soundSelector.open()
+                            }
+                        }
+                    }
+
                     QQC2.CheckBox {
                         text: i18n("Show in history")
                         checked: !!behaviorSettings && behaviorSettings.showInHistory
@@ -426,6 +499,10 @@ ColumnLayout {
         nameFilters: ["Sound files(*.ogg *.oga *.wav)"]

         onAccepted: {
+            if (eventRow === -1) {
+                behaviorSettings.sound = selectedFile.toString()
+                return
+            }
             kcm.sourcesModel.setData(kcm.sourcesModel.index(eventRow, 0, eventsModel.rootIndex), selectedFile, Private.SourcesModel.SoundRole)
         }
     }
diff --git a/libnotificationmanager/kcfg/behaviorsettings.kcfg b/libnotificationmanager/kcfg/behaviorsettings.kcfg
index 31d74218c8..c102c530a9 100644
--- a/libnotificationmanager/kcfg/behaviorsettings.kcfg
+++ b/libnotificationmanager/kcfg/behaviorsettings.kcfg
@@ -20,5 +20,11 @@
         <entry name="ShowBadges" type="Bool">
             <default>true</default>
         </entry>
+        <entry name="PlaySound" type="Bool">
+            <default>false</default>
+        </entry>
+        <entry name="Sound" type="String">
+            <default>message-new-instant</default>
+        </entry>
     </group>
 </kcfg>
diff --git a/libnotificationmanager/notifications.cpp b/libnotificationmanager/notifications.cpp
index baa61cecc9..6bd0cef21b 100644
--- a/libnotificationmanager/notifications.cpp
+++ b/libnotificationmanager/notifications.cpp
@@ -8,6 +8,7 @@

 #include <QConcatenateTablesProxyModel>
 #include <QDebug>
+#include <QDir>
 #include <QFile>
 #include <QMetaEnum>
 #include <QPointer>
@@ -32,6 +33,7 @@

 #include "jobsmodel.h"

+#include "behaviorsettings.h"
 #include "settings.h"

 #include "notification.h"
@@ -1081,6 +1083,20 @@ void Notifications::playSoundHint(const QModelIndex &idx) const
     auto desktopFile = data(idx, Notifications::DesktopEntryRole).toString();
     auto appName = data(idx, Notifications::ApplicationNameRole).toString();

+    // Applications without their own notification events can be configured to play a sound
+    if (!isSuppressSound && soundName.isEmpty() && soundFilePath.isEmpty() && data(idx, Notifications::NotifyRcNameRole).toString().isEmpty()) {
+        BehaviorSettings behavior(QStringLiteral("Applications"), Utils::settingsDesktopEntry(idx));
+        behavior.load();
+        if (behavior.playSound()) {
+            const QString sound = behavior.sound();
+            if (sound.startsWith(QLatin1String("file:")) || QDir::isAbsolutePath(sound)) {
+                soundFilePath = QUrl::fromUserInput(sound).toLocalFile();
+            } else {
+                soundName = sound;
+            }
+        }
+    }
+
     if (isSuppressSound || (soundName.isEmpty() && soundFilePath.isEmpty())) {
         return;
     }
-- 
2.53.0
